const schemaText = $input.first().json?.data ?? $input.first().json ?? '';
const body = $('Webhook — Trigger Manual').first().json.body ?? $('Webhook — Trigger Manual').first().json;
const clientId = (body.client_id ?? '').toString().trim() || null;
if (!schemaText || String(schemaText).trim().length < 100) {
  throw new Error('Schema SQL inválido ou vazio — verifique C8_SCHEMA_RAW_URL');
}
console.log(clientId ? `Atualização individual: ${clientId}` : 'Atualização em massa');
return [{ json: { client_id: clientId, schema_sql: String(schemaText) } }];

const clientId = $('Preparar Schema e Modo').first().json.client_id;
const schemaSql = $('Preparar Schema e Modo').first().json.schema_sql;
const raw = $input.first().json;
let clients = Array.isArray(raw) ? raw : (raw.data ?? raw ?? []);
clients = clients.filter(c => c.supabase_url && c.service_key);
if (clientId) {
  clients = clients.filter(c => c.client_id === clientId);
  if (clients.length === 0) throw new Error(`Cliente ${clientId} não encontrado ou sem credenciais.`);
}
console.log(`Clientes para atualização: ${clients.length}`);
return clients.map(c => ({ json: { ...c, schema_sql: schemaSql } }));

const results = $input.all();
const total   = results.length;
const success = results.filter(r => r.json.success !== false).length;
const failed  = total - success;
const failures = results.filter(r => r.json.success === false)
  .map(r => ({ client_id: r.json.client_id ?? 'desconhecido', error: r.json.error }));
if (failures.length > 0) console.error('Falhas:', JSON.stringify(failures));
return [{ json: { total, success, failed, failures, updated_at: new Date().toISOString() } }];
